import styled from '@emotion/styled';
import { Close } from '@mui/icons-material';
import { Alert, AlertTitle, Button, Snackbar } from '@mui/material';
import { useStaticQuery } from 'gatsby';
import { IconButton } from 'gatsby-theme-material-ui';
import React, { useState } from 'react';
import { useMemo } from 'react';
import { useAllMusic } from '../../hooks/useAllMusic';
import { useAllProjects } from '../../hooks/useAllProjects';
import ItemMap from './ItemMap';
import { ItemMap__Props } from './ItemMap';
import { getItemFromMusics, getItemFromProjects } from './SingleItem';
import { useAllSkills } from '../../hooks/useAllSkills';

const ItemWrap = styled.div`
  display: flex;
  gap: 2rem;
  flex-wrap: wrap;
  justify-content: center;
`;

const AllItems = () => {
  const music = useAllMusic();
  const projects = useAllProjects();

  const [copyOpen, setCopyOpen] = useState(false);

  const mappedData = useMemo(() => {
    const fullArray: ItemMap__Props[] = [
      ...getItemFromProjects(projects),
      ...getItemFromMusics(music),
    ];

    return fullArray;
  }, [music, projects]);

  const onCopyLink = async (link: string) => {
    setCopyOpen(true);
    if (navigator.clipboard) {
      await navigator.clipboard.writeText(link);
    }
  };

  return (
    <>
      <ItemWrap>
        {mappedData.map((i) => (
          <ItemMap key={i.data.id} data={{ ...i.data, onCopyLink }} />
        ))}
      </ItemWrap>
      <Snackbar
        open={copyOpen}
        autoHideDuration={6000}
        onClose={() => setCopyOpen(false)}
        // TransitionProps={{ onExited: handleExited }}
      >
        <Alert
          variant="filled"
          sx={{ color: 'white', backgroundColor: 'primary.main' }}
        >
          <AlertTitle>Copied to Clipboard!</AlertTitle>
        </Alert>
      </Snackbar>
    </>
  );
};

export default AllItems;
